export const Inline = (args) => {
  return (
    <div>
      <Select inline id="select-1" {...args}>
        {selectItems}
      </Select>
    </div>
  );
};

Inline.args = {
  ...sharedArgs,
  inline: true,
};

Inline.argTypes = {
  ...sharedArgTypes,
  inline: {
    ...sharedArgTypes.inline,
    table: { readonly: true },
  },
};

Inline.parameters = {
  controls: { include: sharedControls },
};

export const Skeleton = (args) => {
  return <SelectSkeleton {...args} />;
};

Skeleton.args = {
  hideLabel: false,
};

Skeleton.argTypes = {
  hideLabel: {
    control: 'boolean',
  },
};

Skeleton.parameters = {
  controls: { include: ['hideLabel'] },
};

export const _WithLayer = (args) => (
